mapper.select:
select
t.sensor_id sensorId,
t.machine_id machineId,
t.sensor_type sensorType,
t.community_id communityId,
t.min_value minValue,
t.max_value maxValue1,
t.units,
t.create_time createTime,
t.status_cd statusCd
from instrument_sensor t
where 1 =1

    and t.min_value= #{minValue}


    and t.machine_id= #{machineId}


    and t.max_value= #{maxValue}


    and t.sensor_type= #{sensorType}


    and t.status_cd= #{statusCd}


    and t.units= #{units}


    and t.community_id= #{communityId}


    and t.sensor_id= #{sensorId}

order by t.create_time desc

    limit #{page}, #{row}

